let state={version:1,brands:{},collections:[]},storageError='';
try{const saved=localStorage.getItem(KEY);if(saved){const v=JSON.parse(saved);if(v.version!==1||!Array.isArray(v.collections)||!v.brands)throw Error('Nieprawidłowa kopia danych');state=v}}catch(e){storageError='Nie można odczytać danych. Oryginalny zapis pozostaje zachowany: '+e.message;}
const catalog=typeof GBP_AUTO_BRANDS!=='undefined'?GBP_AUTO_BRANDS:{};
const brands=[...new Set([...Object.keys(catalog),'Paradyż',...Object.keys(state.brands),...state.collections.map(c=>c.brand)])];
brands.forEach(b=>{if(!state.brands[b])state.brands[b]={description:'',keywords:'',target:'/plytki/'+slug(b)+'/',styles:''};});
Object.entries(catalog).forEach(([b,v])=>v.collections.forEach(name=>{if(!state.collections.some(c=>norm(c.brand)===norm(b)&&norm(c.name)===norm(name))){const c=empty(b,name);c.source=v.source;state.collections.push(c)}}));

